Definition map_or_die_seg1_post (ra sp gp tp t0 t1 t2 s5 a6 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (lo beg size name : Z) (s0 s1 s2 s3 s4 : word) : machine_state -> Prop :=
  fun ms' => exists m' (j44 : list byte),
    ms' = MS (mkR (wz 0x088a18) (Z_to_bv 64 (bv_unsigned sp + -128)) gp tp t0 t1 t2 (wz size) (wz 1) (wz beg) (wz size) (wz 3) (wz 50) (Z_to_bv 64 (-1)) (wz 0) a6 (wz 222)
                  (wz beg) (wz name) (wz APAGESZ) s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 0x086c58) fc None m' (seg_rom bsegs)
    /\ munch [(bv_unsigned sp - 400, bv_unsigned sp)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp + -128)
    /\ rw_cells bsegs m' (bv_unsigned sp + -128) [C4 (wz 50); CB 44 j44; C8 s4; C8 s3; C8 s2; C8 (wz beg); C8 (wz size); C8 (wz 0x092084)]   (* [comment removed for export] *)
    /\ rw_cells bsegs m' (bv_unsigned sp + -32) [C8 s2; C8 s1; C8 s0; C8 ra].                                                            (* [comment removed for export] *)

