            (F : bvmap 5 word) (fc : bv 32) (m : mem).
  Variables (lo beg size name : Z).
  Hypothesis MI : mem_inv bsegs m.
  Hypothesis ST : stk bsegs m lo (bv_unsigned sp).
  Hypothesis LO : aceil <= lo.  Hypothesis HI : lo + 400 <= bv_unsigned sp.   (* [comment removed for export] *)
