  Hypothesis BEG : 0 <= beg /\ beg + size <= 2^47 /\ beg mod 4096 = 0.
  Hypothesis SZ : 0 < size /\ size mod 4096 = 0.
  Hypothesis NM : 0 < name < 2^32.
