(* [comment removed for export] *)
Definition map_seg2_post (ra : word) (spi : Z) (gp tp t0 t1 t2 s0 s1 s2 s3 s4 s5 a6 a7 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (lo r : Z) : machine_state -> Prop :=
  fun ms' => exists (a1 a2 a3 a4 a5 : word) m',
    ms' = MS (mkR ra (Z_to_bv 64 (spi + 128)) gp tp t0 t1 t2 s0 s1 (wz r) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(spi, spi + 96)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (spi + 128).

Section Seg2M.
  Variables (ra gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
            (F : bvmap 5 word) (fc : bv 32) (m : mem).
  Variables (spi lo r size : Z) (s1v s2v s3v s0i s1i s2i : word) (j44 : list byte).
  Hypothesis MI : mem_inv bsegs m.
  Hypothesis ST : stk bsegs m lo spi.
  Hypothesis LO : aceil <= lo.  Hypothesis HI : lo <= spi. Hypothesis SPT : spi + 144 <= 2^47. Hypothesis SPA : spi mod 8 = 0.
  Hypothesis FR : rw_cells bsegs m spi [C4 (wz 50); CB 44 j44; C8 s4; C8 s3; C8 s2i; C8 s1i; C8 s0i; C8 (wz 0x092084)].
  Hypothesis FR2 : rw_cells bsegs m (spi + 96) [C8 s2; C8 s1; C8 s0; C8 ra].
  Hypothesis RR : 0 < r /\ r + 4096 <= 2^47.
  Hypothesis SZ : 0 < size < 2^47.
  Hypothesis GOT : rw_cells bsegs m AGOT_LO (map (fun v => C8 (wz v)) AGOT_VALS).
  Hypothesis MLIM : rw_cells bsegs m (ACFLAGS + 144) [C8 (wz 0)].

  Theorem map_seg2 :
    evt bsegs (map_seg2_post ra spi gp tp t0 t1 t2 s0 s1 s2 s3 s4 s5 a6 a7 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m lo r)
      (MS (mkR (wz 0x088a18) (Z_to_bv 64 spi) gp tp t0 t1 t2 (wz size) s1v (wz r) a1 a2 a3 a4 a5 a6 a7
               s2v s3v (wz APAGESZ) s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
          F (Z_to_bv 64 0x086c5c) fc None m (seg_rom bsegs)).
